CREATE OR REPLACE TABLE TRADING.FIRM_RATING (FIRM_ID INTEGER, FROM_Z DATE, THRU_Z DATE, AGENCY VARCHAR(16), GRADE VARCHAR(8), PRIMARY KEY (FIRM_ID, FROM_Z));
CREATE OR REPLACE TABLE TRADING.PRODUCT_LIMIT (TICKER VARCHAR(16), FROM_Z DATE, IN_Z DATE, THRU_Z DATE, OUT_Z DATE, MAX_QTY INTEGER, PRIMARY KEY (TICKER, FROM_Z, IN_Z));
